package com.mamtrex.hospital.hr;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/shifts") public class ShiftController { private final ShiftRepository repo; private final AuditService audit; public ShiftController(ShiftRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String staffId, @jakarta.validation.constraints.NotBlank String department, @jakarta.validation.constraints.NotBlank String startsAt, @jakarta.validation.constraints.NotBlank String endsAt, @jakarta.validation.constraints.NotBlank String status){} @PostMapping public Shift create(@Valid @RequestBody Request r){var e=repo.save(new Shift(r.staffId(), r.department(), r.startsAt(), r.endsAt(), r.status()));audit.record("CREATE","Shift",e.getId().toString(),"created");return e;} @GetMapping public List<Shift> list(){return repo.findAll();} @GetMapping("/{id}") public Shift get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Shift not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("Shift not found: "+id);repo.deleteById(id);audit.record("DELETE","Shift",id.toString(),"deleted");} }
